  // --- Big separator icons -------------------------------------------------
  // These ride the conference separator ("BIG TEN / FOOTBALL [ball]") rather than
  // every card, so they get room to be ~24px and actually legible.
  //
  // Rasterised from geometry, not stored as ASCII: a hand-typed 23x23 grid is 23
  // rows of exactly 23 characters, and one miscounted row renders wrong in a way
  // review won't catch. Testing a predicate at each pixel centre gives the same
  // hard-edged, un-antialiased result as the small hand-drawn art (we still never
  // stroke a path — that's what smears at this size), at any size we ask for.
  // Returns 0 = off, 1 = body, 2 = accent.
  const SPORT_SHAPE = {
    // Fat ellipse + laces. The taper has to stay at the very ends or it reads as
    // a diamond (learned the hard way on the 11px version).
    FOOTBALL: { w: 25, h: 15, body: '#a55a2a', accent: '#ffffff', at: (dx, dy, W, H) => {
      if ((dx / (W / 2 - 0.4)) ** 2 + (dy / (H / 2 - 0.4)) ** 2 > 1) return 0;
      const bar = Math.abs(dy) < 0.7 && Math.abs(dx) <= 5.5;
      const tick = Math.abs(dy) <= 2.4 && Math.abs(dy) >= 0.7 && [-4, -2, 0, 2, 4].indexOf(Math.round(dx)) >= 0;
      return (bar || tick) ? 2 : 1;
    } },
    // Side seams that bow outward at the equator. No equator line — on the 9px
    // version that quartered the ball into a letter H.
    BASKETBALL: { w: 23, h: 23, body: '#ff8c00', accent: '#ff8c00', at: (dx, dy, W) => {
      const R = W / 2 - 0.4;
      if (dx * dx + dy * dy > R * R) return 0;
      const bow = 4.6 + 2.4 * (1 - Math.abs(dy) / R);
      return Math.abs(Math.abs(dx) - bow) < 0.8 ? 0 : 1;
    } },
    // White ball, red stitches curving inward at the middle.
    BASEBALL: { w: 23, h: 23, body: '#ffffff', accent: '#ff2020', at: (dx, dy, W) => {
      const R = W / 2 - 0.4;
      if (dx * dx + dy * dy > R * R) return 0;
      const bow = 7.8 - 2.8 * (1 - Math.abs(dy) / R);
      return Math.abs(Math.abs(dx) - bow) < 0.75 ? 2 : 1;
    } },
    // Squashed disc, lit rim on top. The flat silhouette is what says "puck".
    HOCKEY: { w: 25, h: 13, body: '#9a9a9a', accent: '#ffffff', at: (dx, dy, W, H) => {
      if ((dx / (W / 2 - 0.4)) ** 2 + (dy / (H / 2 - 0.4)) ** 2 > 1) return 0;
      return dy < -(H / 2 - 3.2) ? 2 : 1;
    } },
    // White ball, dark centre pentagon + three short seams. The seams must STOP
    // short of the rim: run them all the way out and they sever the disc into
    // three floating blobs that read as a propeller, not a ball.
    SOCCER: { w: 23, h: 23, body: '#ffffff', accent: '#ffffff', at: (dx, dy, W) => {
      const R = W / 2 - 0.4;
      const r = Math.hypot(dx, dy);
      if (r > R) return 0;
      const a = Math.atan2(dy, dx);
      if (r <= 4.6) { // regular pentagon, point up
        const k = Math.cos(Math.PI / 5) / Math.cos(((a + Math.PI / 2 + 2 * Math.PI) % (2 * Math.PI / 5)) - Math.PI / 5);
        if (r <= 4.4 * k) return 0;
      }
      for (const sa of [-Math.PI / 2, Math.PI / 6, 5 * Math.PI / 6]) {
        const d = Math.abs(((a - sa + Math.PI + 2 * Math.PI) % (2 * Math.PI)) - Math.PI);
        if (d < 0.2 && r > 4.0 && r < R - 2.6) return 0; // stop short: keep the rim whole
      }
      return 1;
    } },
  };

  const _icons = {};
  function iconSprite(name) {
    let c = _icons[name];
    if (c !== undefined) return c;
    const shape = SPORT_SHAPE[name];
    if (shape) {
      c = document.createElement('canvas');
      c.width = shape.w; c.height = shape.h;
      const g = c.getContext('2d');
      const cx = (shape.w - 1) / 2, cy = (shape.h - 1) / 2;
      for (let y = 0; y < shape.h; y++) {
        for (let x = 0; x < shape.w; x++) {
          const v = shape.at(x - cx, y - cy, shape.w, shape.h);
          if (!v) continue;
          g.fillStyle = v === 2 ? shape.accent : shape.body;
          g.fillRect(x, y, 1, 1);
        }
      }
      return (_icons[name] = c);
    }
    const art = ICON_ART[name];
    if (!art) return (_icons[name] = null);
    const h = art.rows.length, w = art.rows[0].length;
    c = document.createElement('canvas');
    c.width = w; c.height = h;
    const g = c.getContext('2d');
    for (let r = 0; r < h; r++) {
      for (let col = 0; col < w; col++) {
        const ch = art.rows[r][col];
        // !ch guards a short row: rows[r][col] === undefined must stay unlit,
        // not fall through to the body colour.
        if (!ch || ch === '.') continue;
        // Multi-colour art carries a palette ({char: colour}); the classic
        // two-colour icons keep '#' = body, 'o' = accent.
        g.fillStyle = (art.palette && art.palette[ch]) ||
          (ch === 'o' ? art.accent : art.body);
        g.fillRect(col, r, 1, 1);
      }
    }
    return (_icons[name] = c);
  }
  function iconW(name) { const s = iconSprite(name); return s ? s.width : 0; }
  // Draw with the icon's vertical centre on cy.
  function icon(ctx, name, x, cy) {
    const s = iconSprite(name);
    if (!s) return 0;
    if (ctx) ctx.drawImage(s, Math.round(x), Math.round(cy - s.height / 2));
    return s.width;
  }

  // ---------------------------------------------------------------------------
  // SCOREBOARD — game_renderer.py render_game_card. Full-height logos flanking a
  // centered "AWAY-HOME" score (16px outlined), status top, down&distance bottom
  // (colored). Fixed 128px card.
  // ---------------------------------------------------------------------------
  const CARD_W = 128;
  const LOGO = 30;
  // ---------------------------------------------------------------------------
  // TEAM LOGO SIZES — exactly two, project-wide (2026-08-10 audit).
  // The same team logo used to draw at six different sizes depending on which
  // segment you caught it in (46 / 44 / 30 / 24 / 18 / 28), which is what Jeff
  // meant by "different sizes of the same logo". There are now two tiers and
  // every team-logo draw site uses one of them:
  //
  //   LOGO_HERO (46) — the logo IS the card: game cards, wordmark cards.
  //                    Deliberately larger than its 28-30px reserved slot, so
  //                    it overflows and crops at the edges rather than
  //                    reflowing layout (Jeff's 2026-07-23/24 bumps).
  //   LOGO_LIST (24) — the logo is a row label sharing the card with several
  //                    others: leaders, top-25, draft, standings, conference
  //                    separators, the Michigan block.
  //
  // Two documented exceptions, both structural rather than drift:
  //   - the scoring takeover keeps its own size (the animation is full-panel and
  //     bounces the logo, so it can't exceed the 32px panel height);
  //   - market cards draw a COMPANY logo (Apple, Coinbase), not a team logo —
  //     different asset class, sized to the market card, left at LOGO.
  // Both tiers scale together off one Settings control (2026-08-10, Phase 4),
  // so "make the logos bigger" stops being a code edit. The RATIO between hero
  // and list is fixed — that's the rule above; only the overall size moves.
  const LOGO_HERO_BASE = 46;
  const LOGO_LIST_BASE = 24;
  const LOGO_SCALE = { small: 0.75, medium: 1, large: 1.25 };
  const DENSITY_ORDER = { minimal: 0, standard: 1, full: 2 };
  // Wordmark height cap, its own setting (2026-08-11, Jeff: "the scaling thing
  // with the wordmarks, I kind of liked them big so make it toggleable in the
  // settings just like the logo size"). Separate from logoSize on purpose: that
  // one scales ROUND logos, and the two tiers were locked together so the
  // hero:list ratio holds -- a wordmark is a different shape with a different
  // constraint (the 32-row panel), so it gets its own control.
  //
  // Sizes shifted up one notch 2026-08-11 (Jeff, on the first version: "the
  // large wordmark one is still not as big as how they used to be, like a lot
  // of them even clipped off the screen a bit, whatever it used to be, make
  // that the large version"). So:
  //   small  28 — what medium was
  //   medium 32 — what large was: edge to edge, every mark still whole
  //   large  Infinity — NO CAP, the pre-2026-08-10 behaviour
  //
  // Large therefore CROPS on purpose. 58 of the 258 marks are taller than the
  // 32-row panel (Texas 58, Broncos 57) and `drawTeamMark` centres them, so
  // those lose rows off the top and bottom. That was the bug the 2026-08-10
  // audit fixed; it is now an option, because Jeff looked at both and prefers
  // the bleed. It is opt-in and it is not the default.
  const WM_SCALE = { small: 28, medium: 32, large: Infinity };
  const DISPLAY = { logoSize: 'medium', density: 'standard', wordmarkSize: 'medium' };
  function logoScale() { return LOGO_SCALE[DISPLAY.logoSize] || 1; }
  function wmMaxH() { return WM_SCALE[DISPLAY.wordmarkSize] || WM_SCALE.medium; }
  function LOGO_HERO() { return Math.round(LOGO_HERO_BASE * logoScale()); }
  function LOGO_LIST() { return Math.round(LOGO_LIST_BASE * logoScale()); }
  function density() { return DENSITY_ORDER[DISPLAY.density] == null ? 1 : DENSITY_ORDER[DISPLAY.density]; }

  // "MICH @ OSU" — away @ home. This replaced the league name, which was dead
  // weight: the conference separator immediately before the card already says
  // "BIG TEN / FOOTBALL", so the card was spending its most prominent row
  // repeating the one thing the reader had just been told.
  function matchup(g) {
    const a = String(g.awayTeam || '?').slice(0, 5);
    const h = String(g.homeTeam || '?').slice(0, 5);
    return (a + ' @ ' + h).toUpperCase().slice(0, 14);
  }

  // Odds (spread / O-U / moneyline) removed from the ticker 2026-08-10: the
  // the-odds-api free tier was exhausted and Jeff's call was "I don't want to
  // spend money on anything so remove the odds we don't need them." No paid
  // dependency remains anywhere in the project.

  // --- Bases diamond (MLB) --------------------------------------------------
  // A 7x7 pixel diamond per base, gold when occupied and a dim outline when not,
  // laid out as the real infield: 2B top, 3B left, 1B right. Drawn as pixel rows
  // for the same reason as the sport icons — a stroked path this small smears.
  const DIAMOND = [1, 3, 5, 7, 5, 3, 1]; // lit width per row of a 7x7 diamond
  function baseGlyph(ctx, x, y, on) {
    for (let r = 0; r < 7; r++) {
      const wRow = DIAMOND[r], x0 = x + (7 - wRow) / 2;
      if (on) {
        ctx.fillStyle = C.scoreGold;
        ctx.fillRect(x0, y + r, wRow, 1);
      } else {
        // outline only: the two edge pixels of the row
        ctx.fillStyle = '#7a7a7a';
        ctx.fillRect(x0, y + r, 1, 1);
        ctx.fillRect(x0 + wRow - 1, y + r, 1, 1);
      }
    }
  }
  const BASES_W = 23, BASES_H = 23;
  function basesGlyph(ctx, x, y, bases, outs) {
    const b = bases || [false, false, false];
    baseGlyph(ctx, x + 8, y, b[1]);          // 2B, top
    baseGlyph(ctx, x, y + 8, b[2]);          // 3B, left
    baseGlyph(ctx, x + 16, y + 8, b[0]);     // 1B, right
    // outs: three pips under the diamond, red as they fill
    for (let i = 0; i < 3; i++) {
      ctx.fillStyle = i < (outs || 0) ? C.redzone : '#3a3a3a';
      ctx.fillRect(x + 6 + i * 5, y + 19, 3, 3);
    }
  }

  // --- Big live card --------------------------------------------------------
  // Live games get a wider card of their own: a big red LIVE off to the LEFT of
  // everything (the small flag used to sit on top of the away logo and the
  // matchup, which is exactly what Jeff flagged), then logos, matchup, a 16px
  // score, and every live detail the sport exposes — for baseball that's the
  // bases diamond + outs + count + inning, like the real ChuckBuilds MLB card.
  const LIVE_PX = 16;

  // Up to 3 short 8px lines of sport-specific live state, most useful first.
  function liveLines(g) {
    const L = g.live || {};
    const out = [];
    if (g.league === 'MLB') {
      if (L.detail) out.push([L.detail.slice(0, 8), C.wxHighlight]); // "BOT 9"
      if (L.count) out.push([L.count, C.white]);                     // balls-strikes
      out.push([(L.outs || 0) + ' OUT', C.dim]);
    } else if (g.league === 'NFL' || g.league === 'NCAAF') {
      if (L.clock) out.push([(L.period ? 'Q' + L.period + ' ' : '') + L.clock, C.white]);
      if (L.dnd) out.push([L.dnd.slice(0, 10), L.redZone ? C.redzone : C.dnd]);
      if (g.situation) out.push([g.situation.slice(0, 10), C.dim]);
    } else {
      if (L.detail) out.push([L.detail.slice(0, 10), C.wxHighlight]);
      if (L.clock) out.push([L.clock, C.white]);
    }
    return out.slice(0, 3);
  }

  const FOOTBALL_LEAGUES = { NFL: 1, NCAAF: 1, UFL: 1, CFL: 1 };

  function liveCard(ctx, x, g, measure) {
    // Football gets the stacked-team card with the field graphic; everything
    // else keeps the logo-flanked layout (baseball adds the bases diamond).
    if (FOOTBALL_LEAGUES[g.league]) return fbLiveCard(ctx, x, g, measure);
    const mich = !!g.michigan;
    const main = mich ? MAIZE : C.white;
    const aNick = g.awayName, hNick = g.homeName;
    const score = (g.awayScore || '0') + ' - ' + (g.homeScore || '0');
    const lines = liveLines(g);
    const showBases = g.league === 'MLB';

    // Glance's classic MLB card flanks each team with its H (hits) / E (errors)
    // column — box-score-at-a-glance. Only when ESPN sends the stats.
    const heOf = he => (he && he.h != null) ? ['H:' + he.h, 'E:' + (he.e == null ? 0 : he.e)] : null;
    const aHE = showBases ? heOf(g.awayHE) : null;
    const hHE = showBases ? heOf(g.homeHE) : null;
    const heW = he => he ? Math.max(tw(he[0]), tw(he[1])) + 6 : 0;

    // Wordmark cards (Skybox look) replaced the plain round logo + "AWY @ HME"
    // abbr text (2026-07-21, Jeff: "how come the live ones dont have the
    // wordmarks") -- the mark itself carries team ID now, so the old
    // matchup() abbr line is redundant and dropped; the score gets the centre
    // slot on its own instead of stacking under it.
    const liveW = tw('LIVE', LIVE_PX);
    const showAway = wantWordmark(g, !!g.awayFavorite);
    const showHome = wantWordmark(g, !!g.homeFavorite);
    const aMarkW = teamSlotW(aNick, g.awayTeam, g.league, showAway);
    const hMarkW = teamSlotW(hNick, g.homeTeam, g.league, showHome);
    const scoreW = tw(score, LIVE_PX);
    const infoW = lines.length ? Math.max.apply(null, lines.map(l => tw(l[0]))) : 0;
    const basesW = showBases ? BASES_W + 12 : 0;
    const w = 6 + liveW + 10 + aMarkW + 8 + heW(aHE) + scoreW + 8 + basesW + infoW + (infoW ? 8 : 0) + heW(hHE) + 8 + hMarkW + 8;
    if (measure) return w;

    const heCol = (he, atX) => {
      if (!he) return 0;
      he.forEach((s, i) => text(ctx, atX, 6 + i * 12, s, i ? C.dim : C.white, { px: 8 }));
      return heW(he);
    };
    let cx = x + 6;
    // Big LIVE, clear of everything else.
    text(ctx, cx, 8, 'LIVE', C.redzone, { px: LIVE_PX });
    cx += liveW + 10;
    cx += drawTeamSlot(ctx, cx, g.awayLogo, aNick, g.awayColor, g.awayTeam, g.league, mich && /MICH/.test(g.awayTeam), false, showAway) + 8;
    cx += heCol(aHE, cx);
    text(ctx, cx + (scoreW - tw(score, LIVE_PX)) / 2, 8, score,
      g.scoreChanged ? C.scoreGold : main, { px: LIVE_PX });
    cx += scoreW + 8;
    if (showBases) {
      basesGlyph(ctx, cx, Math.floor((ROWS - BASES_H) / 2), (g.live || {}).bases, (g.live || {}).outs);
      cx += basesW;
    }
    if (infoW) {
      lines.forEach((l, i) => text(ctx, cx, i * 11 + (lines.length === 3 ? 0 : 5), l[0], l[1], { px: 8 }));
      cx += infoW + 8;
    }
    cx += heCol(hHE, cx);
    drawTeamSlot(ctx, cx, g.homeLogo, hNick, g.homeColor, g.homeTeam, g.league, mich && /MICH/.test(g.homeTeam), true, showHome);
    return w;
  }


  // --- Wordmark cards (Skybox look, 2026-07-18) -----------------------------
  // Jeff wants the $1,295 Skybox ticker's team pictures: big logo + the team
  // NICKNAME in team colour (VEGAS grey, PANTHERS red), not a shrunk round logo
  // + a blocky abbr. No wordmark-image source exists across leagues (ESPN only
  // serves round logos), so the "wordmark" is the nickname rendered in the
  // team's colour — which is what most of Skybox's own wordmarks actually are.
  //
  // WORDMARK_ART is the hand-drawn override: a marquee team can supply pixel-art
  // rows (same {palette,rows} shape as ICON_ART) to get its real wordmark
  // typeface; everyone else falls back to nickname text. Registry starts with
  // Jeff's teams and grows one team at a time — each is slow hand-pixel work.
  // Hand-registered team wordmarks. Each is a real team wordmark image (AI-
  // generated in the team's own typeface, per the 2026-07-20 decision — see the
  // Work Log) run through scratchpad/build_registry.py: cropped to ink, scaled
  // to ~26px tall (width-capped 92), thresholded onto the grid.
  //   single-colour marks emit '#' and are TINTED to the team colour by
  //     drawTeamMark (brightColor lifts dark navies/purples so they read).
  //   two-tone marks carry a real palette (F/O) and keep it (_keep path).
  //   tint:false keeps a mark's own colour (white interlock monograms).
  // Keyed by ESPN abbreviation; a 'LEAGUE|ABBR' key wins over bare 'ABBR' so
  // Ravens (NFL|BAL) doesn't hijack the Orioles (MLB BAL) and Cowboys (NFL|DAL)
  // doesn't hijack the Mavericks. Regenerate: python scratchpad/build_registry.py.
